#[path="../source_holes.rs"]mod source_holes;
#[path="../owner_registry.rs"]mod owner_registry;#[path="../owner_budget.rs"]mod owner_budget;#[path="../journal.rs"]mod journal;#[path="../owner.rs"]mod owner;#[path="../face_owner.rs"]mod face_owner;
use ingetrazo_core::mesh::Mesh;use glam::DVec3;use serde_json::json;
fn state(o:&face_owner::FaceOwner,name:&str)->serde_json::Value{let m=o.mesh();json!({"name":name,"vertices":m.vertices.iter().map(|v|v.position.to_array()).collect::<Vec<_>>(),"edges":m.edges.iter().map(|e|json!({"vertices":[e.v0,e.v1],"faces":e.faces})).collect::<Vec<_>>(),"faces":m.faces.iter().map(|f|json!({"outer":f.vertices,"holes":f.holes})).collect::<Vec<_>>()})}
fn main(){let mut o=face_owner::FaceOwner::new(Mesh::new()).unwrap();let mut result=vec![state(&o,"empty")];let mut t=o.begin().unwrap();t.add_face(&[DVec3::ZERO,DVec3::X,DVec3::Y],&[]).unwrap();o.commit(t).unwrap();result.push(state(&o,"triangle"));let mut t=o.begin().unwrap();t.add_face(&[DVec3::X,DVec3::ZERO,-DVec3::Y],&[]).unwrap();o.commit(t).unwrap();result.push(state(&o,"shared"));o.undo().unwrap();result.push(state(&o,"shared-undo"));o.redo().unwrap();result.push(state(&o,"shared-redo"));let mut t=o.begin().unwrap();t.add_face(&[DVec3::new(0.,0.,1.),DVec3::new(4.,0.,1.),DVec3::new(4.,4.,1.),DVec3::new(0.,4.,1.)],&[vec![DVec3::new(1.,1.,1.),DVec3::new(1.,2.,1.),DVec3::new(2.,2.,1.),DVec3::new(2.,1.,1.)]]).unwrap();o.commit(t).unwrap();result.push(state(&o,"hole"));o.undo().unwrap();result.push(state(&o,"hole-undo"));o.redo().unwrap();result.push(state(&o,"hole-redo"));let mut failed=o.begin().unwrap();failed.add_face(&[DVec3::new(30.,0.,0.),DVec3::new(31.,0.,0.),DVec3::new(30.,1.,0.)],&[]).unwrap();failed.abort();assert!(o.commit(failed).is_err());result.push(state(&o,"explicit-error-rollback"));for (name,sign) in [("slanted",1.),("reflected",-1.)]{let mut t=o.begin().unwrap();t.add_face(&[DVec3::new(sign*20.125,0.2,2.3),DVec3::new(sign*21.125,0.2,2.8),DVec3::new(sign*21.125,1.2,3.3),DVec3::new(sign*20.125,1.2,2.8)],&[]).unwrap();o.commit(t).unwrap();result.push(state(&o,name));o.undo().unwrap();result.push(state(&o,&format!("{name}-undo")));o.redo().unwrap();result.push(state(&o,&format!("{name}-redo")));}
let mut o=face_owner::FaceOwner::new(Mesh::new()).unwrap();let mut t=o.begin().unwrap();t.extrude_geometry(&[[10.,0.],[12.,0.],[12.,1.],[10.,1.]],0.25,1.75).unwrap();o.commit(t).unwrap();result.push(state(&o,"extrude-geometry"));o.undo().unwrap();result.push(state(&o,"extrude-undo"));o.redo().unwrap();result.push(state(&o,"extrude-redo"));println!("{}",serde_json::to_string_pretty(&result).unwrap());}
